const cmd = `python3 -c 'exec("""import json
import subprocess
from collections import Counter
from pathlib import Path
from tools.i18nlib.config import load_manifest
from tools.i18nlib.locale_model import LocaleLoader
from tools.i18nlib.runtime import LuaRuntime

root = Path(".")
files = ["mod-tome.lua", "tome-ashes-urhrok.lua", "tome-cults.lua", "tome-orcs.lua"]
workset = json.loads((root / ".ai/task/repair-w50-20260928/WORKSET.json").read_text(encoding="utf-8"))["items"]
expected = {}
for item in workset:
    ident = (item["normalized_path"], item["section"], item["source"], item["source_tag"], item.get("args_order"), item["target_preimage"])
    if ident in expected:
        raise SystemExit("duplicate expected identity")
    expected[ident] = item["entry_revision_identity"]

loader = LocaleLoader(LuaRuntime(load_manifest()))
changes = []
for file in files:
    before_bytes = subprocess.check_output(["git", "show", "HEAD:" + file])
    before = loader.load_bytes(before_bytes, logical_path=file).records
    after = loader.load_path(root / file, logical_path=file).records
    if len(before) != len(after):
        raise SystemExit(f"{file}: record count changed {len(before)} -> {len(after)}")
    for old, new in zip(before, after):
        if old == new:
            continue
        old_fixed = dict(old)
        new_fixed = dict(new)
        old_target = old_fixed.pop("target", None)
        new_target = new_fixed.pop("target", None)
        if old_fixed != new_fixed:
            raise SystemExit(f"{file}: non-target record fields changed")
        if old_target.count("\\\\n") != new_target.count("\\\\n"):
            raise SystemExit(f"{file}: target newline count changed")
        ident = (file, old["section"], old["source"], old.get("source_tag"), old.get("args_order"), old_target)
        key = expected.get(ident)
        if key is None:
            raise SystemExit(f"{file}: changed record outside WORKSET: {old['"'"'source'"'"']!r}")
        changes.append({"key": key, "file": file, "section": old["section"], "source": old["source"], "source_tag": old.get("source_tag"), "before": old_target, "after": new_target})
actual_keys = {change["key"] for change in changes}
expected_keys = {item["entry_revision_identity"] for item in workset}
if len(changes) != 27 or actual_keys != expected_keys:
    raise SystemExit(f"changed target mismatch: count={len(changes)} missing={sorted(expected_keys-actual_keys)} extra={sorted(actual_keys-expected_keys)}")
print(json.dumps({"status": "PASS", "loader": "LocaleLoader via manifest LuaJIT bridge", "changed_targets": len(changes), "unchanged_other_records": True, "by_file": dict(Counter(change["file"] for change in changes)), "changes": changes}, ensure_ascii=False, indent=2))
""")'`;
